-- Նոր ուղեցույցների սևագրերը (⚑ Ճշտել) (ստեղծված է scripts/guides-seed/make-seed.ts-ով). բոլորը՝ «Ստուգման մեջ»։
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('questions', 'Հարց ու պատասխան', 'Կարճ պատասխաններ հաճախ տրվող հարցերին', '', 'link', '/church/questions', 'question', '{"blocks":[],"faq":[]}', '[]', 'draft', 15);
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('liturgy', 'Սուրբ Պատարագ', 'Ինչ է կատարվում Պատարագին և ինչ է նշանակում', 'Սուրբ Պատարագը Եկեղեցու գլխավոր արարողությունն է, որի ընթացքում կատարվում է Հաղորդության խորհուրդը։ Այստեղ՝ Պատարագի մասերը և դրանց իմաստը։', 'guide', '', 'wine', '{"blocks":[{"id":"what","title":"Ինչ է Պատարագը","text":"«Պատարագ» նշանակում է ընծա, զոհ։ Պատարագին Եկեղեցին հիշում և ներկա է դարձնում Քրիստոսի Վերջին ընթրիքը, Նրա խաչելությունն ու Հարությունը։ Հավատացյալները միասին աղոթում են, լսում Աստծո խոսքը և հաղորդվում։","when":"Կիրակի և տոն օրերին","why":"Քրիստոս պատվիրեց. «Այս արեք իմ հիշատակի համար» (Ղուկ. 22.19)։"},{"id":"preparation","title":"Նախապատրաստություն","text":"Պատարագից առաջ քահանան զգեստավորվում է, լվանում ձեռքերը և խոստովանում իր մեղքերը ժողովրդի առաջ։ Վարագույրը փակ է, երբ պատրաստվում են հացն ու գինին։","steps":"Զգեստավորում → Ձեռքերի լվացում → Խոստովանություն → Ընծաների պատրաստում → Խնկարկություն"},{"id":"word","title":"Խոսքի մաս","text":"Վարագույրը բացվում է։ Երգվում են շարականներ, կարդացվում են Մարգարեություն, Առաքյալի թուղթ և Ավետարան։ Ապա ամբողջ ժողովուրդը ասում է Հավատո հանգանակը («Հավատամք»)։","why":"Նախ լսում ենք Աստծո խոսքը, հետո մոտենում Խորհրդին։"},{"id":"eucharist","title":"Խորհրդական մաս","text":"Սուրբ ընծաները բերվում են Սուրբ Սեղան (Վերաբերում)։ Քահանան ասում է Վերջին ընթրիքի խոսքերը և աղոթում, որ Սուրբ Հոգին իջնի ընծաների վրա։ Ժողովուրդը միասին ասում է «Հայր մեր»-ը։","why":"Եկեղեցին հավատում է, որ հացն ու գինին դառնում են Քրիստոսի Մարմինն ու Արյունը։"},{"id":"communion","title":"Հաղորդություն և արձակում","text":"Պատրաստված հավատացյալները մոտենում են և հաղորդվում։ Վերջում քահանան օրհնում է ժողովրդին, և բաժանվում է մասը՝ օրհնված հացը։","prepare":"Ինչպես պատրաստվել Հաղորդությանը՝ տես «Վարք եկեղեցում» → «Պատարագ և Հաղորդություն»։"}],"faq":[{"q":"Որքա՞ն է տևում Պատարագը","a":"Սովորաբար մոտ մեկուկես–երկու ժամ։ ⚑ Ճշտել"},{"q":"Որտեղի՞ց կարդալ Պատարագի տեքստը","a":"«Պատարագամատույց» էջում՝ գրաբար և աշխարհաբար, ժողովրդի պատասխանները ընդգծված։"}]}', '["⚑ Սևագիր՝ քահանայի ստուգման համար"]', 'review', 40);
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('patarag', 'Պատարագամատույց', 'Պատարագի տեքստը՝ հետևելու համար, ձայնագրությամբ', '', 'link', '/church/patarag', 'book', '{"blocks":[],"faq":[]}', '[]', 'draft', 45);
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('hours', 'Ժամերգություններ', 'Ինը ժամերը՝ գիշերից մինչև հանգստյան', 'Ժամերգությունները Եկեղեցու օրվա աղոթքներն են։ Ըստ Ժամագրքի՝ օրը բաժանված է ինը ժամի. դրանք սովորաբար միավորվում և կատարվում են առավոտյան և երեկոյան։', 'guide', '', 'clock', '{"blocks":[{"id":"gisherayin","title":"Գիշերային ժամ","text":"Աղոթք՝ Քրիստոսի երկրորդ գալստյան սպասումով, երբ աշխարհը քնած է։","when":"Կեսգիշերից հետո"},{"id":"aravotyan","title":"Առավոտյան ժամ","text":"Նվիրված է Քրիստոսի Հարությանը. յուղաբեր կանայք առավոտյան գնացին գերեզման։","when":"Լուսաբացին"},{"id":"arevagal","title":"Արևագալի ժամ","text":"Փառաբանություն Քրիստոսին՝ «Արդարության Արեգակին»։","when":"Արևածագին"},{"id":"errord","title":"Երրորդ ժամ","text":"Հիշատակ Սուրբ Հոգու էջքի առաքյալների վրա։","when":"Առավոտյան ժամը 9-ին"},{"id":"vetserord","title":"Վեցերորդ ժամ","text":"Հիշատակ Քրիստոսի խաչելության։","when":"Կեսօրին"},{"id":"innerord","title":"Իններորդ ժամ","text":"Հիշատակ Քրիստոսի մահվան խաչի վրա։","when":"Կեսօրից հետո՝ ժամը 3-ին"},{"id":"yerekoyan","title":"Երեկոյան ժամ","text":"Գոհություն անցած օրվա համար և հիշատակ Քրիստոսի թաղման։","when":"Մայրամուտին"},{"id":"khaghaghakan","title":"Խաղաղական ժամ","text":"Աղոթք խաղաղ գիշերի և հոգու խաղաղության համար։","when":"Երեկոյից հետո"},{"id":"hangstyan","title":"Հանգստյան ժամ","text":"Աղոթք պահպանության համար գիշերը և խնդրանք՝ հանգիստ քնի։","when":"Քնելուց առաջ"}],"faq":[]}', '["⚑ Սևագիր՝ քահանայի ստուգման համար"]', 'review', 50);
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('hymns', 'Շարականներ', 'Եկեղեցական երգեր՝ ըստ տոնի և ժամի, ձայնագրությամբ', '', 'link', '/church/sharakanner', 'music', '{"blocks":[],"faq":[]}', '[]', 'draft', 55);
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('symbols', 'Խորհրդանիշներ և եկեղեցական առարկաներ', 'Խաչ, մոմ, խունկ, սրբապատկեր, քշոց', 'Եկեղեցում ամեն առարկա ունի իր իմաստը։ Այստեղ՝ ամենահաճախ հանդիպողները։', 'guide', '', 'cross', '{"blocks":[{"id":"khach","title":"Խաչ","text":"Քրիստոնեության գլխավոր նշանը՝ Քրիստոսի զոհի և Հարության հաղթանակի։ Հայ Եկեղեցում խաչը օծվում է մյուռոնով, և միայն դրանից հետո է համարվում սուրբ։","why":"Խաչը մահվան գործիք էր, իսկ Քրիստոսով դարձավ փրկության նշան։"},{"id":"mom","title":"Մոմ","text":"Մոմը վառում են աղոթքի ժամանակ։ Այն խորհրդանշում է Քրիստոսի լույսը և մեր աղոթքը, որ բարձրանում է Աստծուն։","tag":"tradition"},{"id":"khunk","title":"Խունկ և բուրվառ","text":"Խունկը ծխում է բուրվառի մեջ։ Քահանան կամ սարկավագը խնկարկում է Սեղանը, սրբապատկերները և ժողովրդին։","why":"«Թող իմ աղոթքը խնկի պես ուղիղ լինի քո առաջ» (Սաղմ. 140.2)։"},{"id":"srbapatker","title":"Սրբապատկեր","text":"Քրիստոսի, Աստվածածնի և սրբերի պատկերները։ Հայ Եկեղեցում սրբապատկերը նույնպես օծվում է մյուռոնով։ Սրբապատկերին երկրպագում են ոչ թե որպես առարկայի, այլ պատվում են նրան, ով պատկերված է։"},{"id":"kshots","title":"Քշոց","text":"Կլոր մետաղե սկավառակ՝ զանգուլակներով և սերովբեների պատկերով, ձողի վրա։ Սարկավագները շարժում են այն Պատարագի կարևոր պահերին։","why":"Հիշեցնում է հրեշտակների ներկայությունը Պատարագին։"},{"id":"varagujr","title":"Վարագույր","text":"Բեմի առջևի վարագույրը փակվում է Պատարագի նախապատրաստության, Հաղորդության պատրաստման պահին և Մեծ պահքի ընթացքում։","why":"Մեծ պահքի ժամանակ փակ վարագույրը հիշեցնում է դրախտից արտաքսումը և ապաշխարության ժամանակը։"}],"faq":[]}', '["⚑ Սևագիր՝ քահանայի ստուգման համար"]', 'review', 60);
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('fasting', 'Պահք և ծոմապահություն', 'Ինչ է պահքը, երբ է, ինչ չեն ուտում', 'Պահքը մարմնի և հոգու ժուժկալություն է՝ աղոթքի և ապաշխարության համար։ Օրերի ճշգրիտ ցանկը՝ «Տոնացույց և պահքի օրեր» էջում։', 'guide', '', 'leaf', '{"blocks":[{"id":"what","title":"Ինչ է պահքը","text":"Պահքի օրերին չեն ուտում կենդանական ծագման սնունդ՝ միս, կաթնամթերք, ձու։ Ծոմը ավելի խիստ է՝ որոշ ժամանակ ընդհանրապես չեն ուտում։ Պահքը միայն սննդի մասին չէ. կարևոր է նաև խուսափել մեղքից, շատ աղոթել և բարի գործ անել։","tag":"canon","why":"Քրիստոս Ինքը քառասուն օր պահեց անապատում (Մատթ. 4.2)։"},{"id":"weekly","title":"Չորեքշաբթի և ուրբաթ","text":"Չորեքշաբթին՝ Քրիստոսին մատնելու, ուրբաթը՝ խաչելության հիշատակն է։ Զատկից հետո հիսուն օրը և Ծննդից հետո ութ օրը պահք չկա։","when":"Ամեն շաբաթ, բացի տոնական շրջաններից","tag":"canon"},{"id":"great-lent","title":"Մեծ պահք","text":"Սկսվում է Մեծ պահքի Բարեկենդանից հետո երկուշաբթի և ավարտվում Ավագ շաբաթով։ Ամենաերկար և կարևոր պահքն է։","when":"Զատկից առաջ՝ 48 օր","tag":"canon"},{"id":"shabatapahk","title":"Շաբաթապահքեր","text":"Գլխավոր տոներից առաջ (Ծնունդ, Պայծառակերպություն, Վերափոխում, Խաչվերաց և այլն) երկուշաբթիից ուրբաթ պահք է։","when":"Մեծ տոներից առաջ՝ հինգ օր","tag":"canon"},{"id":"aradjavorats","title":"Առաջավորաց պահք","text":"Հինգօրյա պահք, որ նախորդում է Մեծ պահքին։ Ավանդության համաձայն՝ կապված է Սուրբ Գրիգոր Լուսավորչի և Տրդատ թագավորի ապաշխարության հետ։","when":"Մեծ պահքից երեք շաբաթ առաջ","tag":"tradition"},{"id":"exceptions","title":"Ով կարող է չպահել","text":"Հիվանդները, հղի և կերակրող կանայք, փոքր երեխաները, ճանապարհորդները կարող են մեղմացնել պահքը։ Ավելի լավ է խորհրդակցել քահանայի հետ։","tag":"tradition"}],"faq":[{"q":"Կարելի՞ է ձուկ ուտել պահքին","a":"Հայ Եկեղեցու ավանդական պահքում ձուկը նույնպես չի ուտվում։ ⚑ Ճշտել"},{"q":"Պահքը պարտադի՞ր է","a":"Պահքը Եկեղեցու կանոն է, բայց այն պահում են կամավոր և ըստ ուժի։ Կարևորը սիրտն է, ոչ թե միայն սնունդը։"}]}', '["⚑ Սևագիր՝ քահանայի ստուգման համար"]', 'review', 70);
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('feasts', 'Տոներ և հիշատակություններ', 'Տաղավար տոներ, շարժական և անշարժ տոներ', 'Հայ Եկեղեցու տարին կառուցված է Զատկի շուրջ։ Տոների մի մասը ունի հաստատուն օր, մյուսները շարժվում են Զատկի հետ։', 'guide', '', 'sparkles', '{"blocks":[{"id":"taghavar","title":"Հինգ տաղավար տոները","text":"Սուրբ Ծնունդ և Աստվածահայտնություն, Սուրբ Զատիկ, Պայծառակերպություն (Վարդավառ), Աստվածածնի Վերափոխում, Խաչվերաց։ Դրանց հաջորդ օրը Մեռելոց է՝ ննջեցյալների հիշատակի օր։","tag":"canon"},{"id":"fixed","title":"Անշարժ տոներ","text":"Միշտ նույն օրն են. Սուրբ Ծնունդ՝ հունվարի 6, Տյառնընդառաջ՝ փետրվարի 14, Ավետում՝ ապրիլի 7։ ⚑ Ճշտել"},{"id":"movable","title":"Շարժական տոներ","text":"Կախված են Զատկից. Ծաղկազարդ՝ Զատկից մեկ շաբաթ առաջ, Համբարձում՝ 40-րդ օրը, Հոգեգալուստ՝ 50-րդ օրը, Վարդավառ՝ Զատկից 98 օր հետո։ Վերափոխումը և Խաչվերացը նշվում են օգոստոսի 15-ին և սեպտեմբերի 14-ին ամենամոտ կիրակին։"},{"id":"saints","title":"Սրբերի հիշատակություններ","text":"Սրբերի տոները սովորաբար երեքշաբթի, հինգշաբթի և շաբաթ օրերին են։ Պահքի օրերին և կիրակիներին սրբերի տոն չի նշվում։"},{"id":"calendar","title":"Տոնացույց","text":"Ամեն տարվա ճշգրիտ օրերը՝ «Տոնացույց և պահքի օրեր» էջում։ Մայր Աթոռը ամեն տարի հրատարակում է պաշտոնական տոնացույցը։"}],"faq":[]}', '["⚑ Սևագիր՝ քահանայի ստուգման համար"]', 'review', 80);
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('calendar', 'Տոնացույց և պահքի օրեր', 'Այս տարվա տոները և պահքերը՝ օր առ օր', '', 'link', '/church/calendar', 'calendar', '{"blocks":[],"faq":[]}', '[]', 'draft', 85);
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('when', 'Ի՞նչ անել, երբ…', 'Ծնունդ, պսակ, մահ, խոստովանություն, տնօրհնեք', 'Կյանքի կարևոր պահերին Եկեղեցին մեր կողքին է։ Այստեղ՝ ինչից սկսել։ Ամեն դեպքում նախ կապվեք ձեր ծխի քահանայի հետ։', 'guide', '', 'compass', '{"blocks":[{"id":"birth","title":"Երեխա է ծնվել","text":"Երեխային մկրտում են սովորաբար մանկության տարիքում։ Ընտրում են կնքահայր (կամ կնքամայր), ով ինքը մկրտված է և պատրաստ է օգնել երեխայի հոգևոր դաստիարակությանը։","tag":"canon","prepare":"Պայմանավորվել քահանայի հետ օրվա մասին։ Պատրաստել սպիտակ շոր, խաչ, մոմ։ ⚑ Ճշտել","steps":"Մկրտություն → Դրոշմ → Առաջին Հաղորդություն"},{"id":"wedding","title":"Ուզում ենք պսակվել","text":"Պսակի խորհուրդը կատարվում է եկեղեցում։ Երկուսն էլ պետք է մկրտված լինեն։","tag":"canon","prepare":"Նախօրոք դիմել քահանային, խոստովանվել և հաղորդվել։ Ընտրել խաչեղբայր։ Պսակ չի կատարվում պահքի օրերին և տաղավար տոներին։ ⚑ Ճշտել"},{"id":"death","title":"Մարդ է մահացել","text":"Կապվեք քահանայի հետ՝ թաղման կարգի և օրվա համար։ Հիշատակության օրերն են Այգուց, Յոթնօրեք, Քառասունք, Տարելից։","prepare":"Մանրամասն՝ «Հիշատակության օրեր» և «Կարգեր» → «Թաղման կարգ»։"},{"id":"confession","title":"Ուզում եմ խոստովանվել","text":"Խոստովանությունը կարելի է անել քահանայի մոտ՝ նախապես պայմանավորվելով, կամ Պատարագից առաջ՝ ընդհանուր խոստովանությամբ։","tag":"canon","prepare":"Մտածել անցած կյանքի մասին, զղջալ և որոշել ուղղվել։ Հաղորդվելուց առաջ՝ պահք և աղոթք։"},{"id":"house-blessing","title":"Ուզում ենք տնօրհնեք","text":"Տնօրհնեքը տան օրհնության կարգ է։ Սովորաբար կատարվում է Սուրբ Ծննդից և Զատկից հետո, նաև նոր տուն տեղափոխվելիս։","tag":"tradition","prepare":"Պայմանավորվել քահանայի հետ։ Սեղանին դնել ջուր, հաց, աղ, մոմ։ ⚑ Ճշտել"}],"faq":[]}', '["⚑ Սևագիր՝ քահանայի ստուգման համար"]', 'review', 90);
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('rites', 'Կարգեր', 'Թաղում, հոգեհանգիստ, մատաղ, ջրօրհնեք, խաղողօրհնեք', 'Կարգերը խորհուրդներ չեն, այլ Եկեղեցու օրհնության և աղոթքի արարողություններ։ Դրանք գրված են Մաշտոց գրքում։', 'guide', '', 'scroll', '{"blocks":[{"id":"funeral","title":"Թաղման կարգ","text":"Քահանան աղոթում է ննջեցյալի հոգու համար, կարդացվում են Սաղմոսներ և Ավետարան, երգվում են շարականներ։ Կարգը կարող է կատարվել եկեղեցում, տանը կամ գերեզմանատանը։","when":"Մահից հետո՝ թաղման օրը","tag":"canon"},{"id":"requiem","title":"Հոգեհանգստյան կարգ","text":"Կարճ աղոթք ննջեցյալների համար։ Հաճախ կատարվում է Պատարագի վերջում։ Կարելի է պատվիրել եկեղեցում՝ անունները տալով քահանային։","when":"Հիշատակության օրերին","tag":"canon"},{"id":"matagh","title":"Մատաղ","text":"Մատաղը գոհության և ողորմության ընծա է։ Քահանան օրհնում է աղը, և դրանով պատրաստված կերակուրը բաժանվում է մարդկանց, հատկապես կարիքավորներին։","tag":"tradition","why":"Մատաղը մեղքերի քավության զոհ չէ. Քրիստոսի զոհից հետո արյունով զոհ պետք չէ։ Այն սիրո և բարեգործության արարք է։"},{"id":"jrorhnek","title":"Ջրօրհնեք","text":"Ի հիշատակ Քրիստոսի մկրտության Հորդանանում՝ քահանան խաչը ընկղմում է ջրի մեջ և մյուռոն կաթեցնում։ Օրհնված ջուրը մարդիկ տանում են տուն։","when":"Սուրբ Ծննդյան և Աստվածահայտնության օրը (հունվարի 6)","tag":"canon"},{"id":"khaghoghorhnek","title":"Խաղողօրհնեք","text":"Օրհնվում է տարվա առաջին բերքը՝ խաղողը, և բաժանվում ժողովրդին։ Ավանդաբար մինչ այդ նոր խաղող չեն ուտում։","when":"Աստվածածնի Վերափոխման տոնին","tag":"tradition"}],"faq":[]}', '["⚑ Սևագիր՝ քահանայի ստուգման համար"]', 'review', 100);
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('structure', 'Եկեղեցու կառույցը', 'Սեղան, բեմ, ատյան, գավիթ', 'Հայկական եկեղեցին կառուցված է արևելքից արևմուտք. Սուրբ Սեղանը միշտ արևելյան կողմում է։', 'guide', '', 'church', '{"blocks":[{"id":"altar","title":"Սուրբ Սեղան և Խորան","text":"Բեմի վրա է, որտեղ մատուցվում է Պատարագը։ Սեղանի վրա են Ավետարանը, խաչը և սկիհը։","why":"Արևելքը դրախտի և Քրիստոսի երկրորդ գալստյան կողմն է։"},{"id":"bem","title":"Բեմ","text":"Բարձրացված մաս՝ ատյանից առաջ։ Վարագույրը բաժանում է այն ժողովրդից։ Բեմ բարձրանում են միայն ծառայողները։"},{"id":"atyan","title":"Ատյան","text":"Եկեղեցու կենտրոնական մասը, որտեղ կանգնում է ժողովուրդը։"},{"id":"avandatun","title":"Ավանդատներ","text":"Սեղանի երկու կողմի փոքր սենյակները, որտեղ պահվում են սրբազան անոթները և զգեստները։"},{"id":"gavit","title":"Գավիթ և մկրտարան","text":"Գավիթը եկեղեցու մուտքի մասն է։ Մկրտության ավազանը սովորաբար հյուսիսային կողմում է։ ⚑ Ճշտել"}],"faq":[]}', '["⚑ Սևագիր՝ քահանայի ստուգման համար"]', 'review', 110);
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('clergy', 'Հոգևորականության աստիճաններ և զգեստներ', 'Սարկավագ, քահանա, վարդապետ, եպիսկոպոս, կաթողիկոս', 'Եկեղեցում կա ձեռնադրության երեք մեծ աստիճան՝ սարկավագ, քահանա, եպիսկոպոս։ Դրանցից առաջ են դպիրները։', 'guide', '', 'hand', '{"blocks":[{"id":"dpir","title":"Դպիրներ","text":"Ծառայողներ, որոնք օգնում են Պատարագին՝ ընթերցում, երգում, մոմեր վառում։ Ունեն չորս աստիճան՝ դռնապան, ընթերցող, երդմնեցուցիչ, ջահընկալ, ապա կիսասարկավագ։"},{"id":"sarkavag","title":"Սարկավագ","text":"Օգնում է քահանային Պատարագի ժամանակ, խնկարկում, կարդում Ավետարանը, բարձրացնում Սուրբ Սկիհը։ Կրում է ուրար՝ ձախ ուսին։"},{"id":"kahana","title":"Քահանա","text":"Կատարում է խորհուրդները (բացի Ձեռնադրությունից) և հովվում է ծուխը։ Ամուսնացած քահանան ծխի հոգևոր հայրն է։ Դիմում են՝ «Տեր հայր»։","steps":"Զգեստներ՝ շապիկ, փորուրար, գոտի, բազպաններ, վակաս, շուրջառ, սաղավարտ։"},{"id":"vardapet","title":"Վարդապետ","text":"Կուսակրոն (չամուսնացած) հոգևորական, ով ստացել է քարոզելու և ուսուցանելու իշխանություն։ Կրում է սև վեղար և գավազան։ ⚑ Ճշտել"},{"id":"yepiskopos","title":"Եպիսկոպոս","text":"Ձեռնադրում է հոգևորականներին և օծում եկեղեցիները։ Ընտրվում է կուսակրոն հոգևորականներից։ Կրում է խույր, եմիփորոն և գավազան։ Դիմում են՝ «Սրբազան հայր»։"},{"id":"katoghikos","title":"Կաթողիկոս","text":"Եկեղեցու գլուխն է։ Ամենայն Հայոց Կաթողիկոսի աթոռը Մայր Աթոռ Սուրբ Էջմիածինն է։ Դիմում են՝ «Վեհափառ Հայրապետ»։"}],"faq":[]}', '["⚑ Սևագիր՝ քահանայի ստուգման համար"]', 'review', 120);
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('creed', 'Հավատո հանգանակ և դավանանք', 'Ինչին ենք հավատում', 'Հայ Առաքելական Եկեղեցու հավատքը ամփոփված է Հավատո հանգանակում, որը ժողովուրդը ասում է ամեն Պատարագի ժամանակ։', 'guide', '', 'book-open', '{"blocks":[{"id":"creed","title":"Հավատո հանգանակ («Հավատամք»)","text":"Նիկիական հանգանակն է՝ Սուրբ Երրորդության, Քրիստոսի մարդեղության, Եկեղեցու և հավիտենական կյանքի մասին։ Տեքստը կավելացվի ադմինից՝ ստուգված աղբյուրից։ ⚑ Ճշտել","tag":"canon"},{"id":"trinity","title":"Սուրբ Երրորդություն","text":"Մեկ Աստված՝ երեք անձով. Հայր, Որդի և Սուրբ Հոգի։"},{"id":"christ","title":"Քրիստոս","text":"Աստծո Որդին մարդացավ Սուրբ Կույս Մարիամից, լինելով կատարյալ Աստված և կատարյալ մարդ, միավորված մեկ բնության մեջ՝ առանց խառնման և բաժանման։ ⚑ Ճշտել"},{"id":"councils","title":"Երեք տիեզերական ժողովները","text":"Հայ Եկեղեցին ընդունում է առաջին երեք տիեզերական ժողովները՝ Նիկիա (325), Կոստանդնուպոլիս (381), Եփեսոս (431)։"},{"id":"church","title":"Առաքելական Եկեղեցի","text":"Եկեղեցին կոչվում է Առաքելական, որովհետև Հայաստանում քրիստոնեությունը քարոզեցին Թադեոս և Բարթողիմեոս առաքյալները։ 301 թվականին Սուրբ Գրիգոր Լուսավորչի միջոցով Հայաստանը քրիստոնեությունն ընդունեց որպես պետական կրոն։"}],"faq":[]}', '["⚑ Սևագիր՝ քահանայի ստուգման համար"]', 'review', 130);
INSERT OR IGNORE INTO guides (slug, title, description, summary, kind, link, icon, body_json, sources_json, status, sort) VALUES ('books', 'Եկեղեցական գրքեր', 'Ժամագիրք, Շարակնոց, Մաշտոց, Ճաշոց, Հայսմավուրք', 'Եկեղեցու արարողությունները կատարվում են ըստ մի քանի գրքերի։ Ահա գլխավորները։', 'guide', '', 'library', '{"blocks":[{"id":"bible","title":"Աստվածաշունչ","text":"Սուրբ Գիրքը։ Հայերեն թարգմանվել է V դարում՝ Սուրբ Մեսրոպ Մաշտոցի և Սահակ Պարթևի գլխավորությամբ։"},{"id":"zhamagirk","title":"Ժամագիրք","text":"Ժամերգությունների աղոթքները և սաղմոսները։"},{"id":"sharaknots","title":"Շարակնոց","text":"Եկեղեցական երգերի՝ շարականների ժողովածուն, դասավորված ըստ տոների և ձայնեղանակների։"},{"id":"mashtots","title":"Մաշտոց","text":"Խորհուրդների և կարգերի գիրքը (մկրտություն, պսակ, թաղում, օրհնություններ)։"},{"id":"pataragamatuyts","title":"Պատարագամատույց","text":"Սուրբ Պատարագի կարգը և աղոթքները։"},{"id":"chashots","title":"Ճաշոց","text":"Աստվածաշնչի ընթերցումները՝ ըստ տարվա օրերի։"},{"id":"haysmavurk","title":"Հայսմավուրք","text":"Սրբերի վարքերը՝ ըստ օրերի։"},{"id":"narek","title":"Նարեկ","text":"Սուրբ Գրիգոր Նարեկացու «Մատյան ողբերգության»՝ աղոթքների գիրք, որը կարդում են նաև տանը։","tag":"tradition"}],"faq":[]}', '["⚑ Սևագիր՝ քահանայի ստուգման համար"]', 'review', 140);
